def get_records(records, start_date=None, end_date=None, sort_by='priority'):
    """
    Retrieves records from a list, filtering by date range and sorting by priority.

    Args:
        records (list): A list of dictionaries, where each dictionary represents a record.
        start_date (str, optional): The start date for filtering (YYYY-MM-DD). Defaults to None.
        end_date (str, optional): The end date for filtering (YYYY-MM-DD). Defaults to None.
        sort_by (str, optional): The field to sort by ('priority' or 'date'). Defaults to 'priority'.

    Yields:
        dict: A record that meets the filtering criteria and is sorted according to the specified field.
    """

    filtered_records = (
        r for r in records
        if start_date is None or start_date <= r.get('date', '')
        if end_date is None or end_date >= r.get('date', '')
    )

    if sort_by == 'priority':
        sorted_records = sorted(filtered_records, key=lambda r: r.get('priority', 0))
    elif sort_by == 'date':
        sorted_records = sorted(filtered_records, key=lambda r: r.get('date', ''))
    else:
        sorted_records = filtered_records

    for r in sorted_records:
        yield r
