def calculate_shipping_cost(weight, destination):
    """
    Calculates the shipping cost based on weight and destination.

    Args:
        weight (float): The weight of the package in kg.
        destination (str): The destination of the package ('Domestic' or 'International').

    Returns:
        float: The final shipping cost rounded to two decimal places.
    """
    if weight <= 0:
        return 0.00  # Or raise an exception, depending on desired behavior

    if destination not in ['Domestic', 'International']:
        return 0.00  # Or raise an exception

    if weight < 1:
        cost = 5.00
    elif 1 <= weight <= 5:
        cost = 5.00 + (2 * weight)
    else:
        cost = 15.00 + (weight - 5)

    if destination == 'International':
        cost *= 1.20

    return round(cost, 2)
